-- HubHex — export complet (structure + donnees)
-- Genere le 2026-06-15T07:16:02.979Z
-- Restauration : psql "$DATABASE_URL" -f hubhex_full_dump.sql
-- Attention : contient mots de passe hashes et donnees utilisateur — ne pas commiter.

BEGIN;
SET session_replication_role = replica;

DROP TABLE IF EXISTS project_relations CASCADE;
DROP TABLE IF EXISTS project_journal_entries CASCADE;
DROP TABLE IF EXISTS project_stack_items CASCADE;
DROP TABLE IF EXISTS project_technical_notes CASCADE;
DROP TABLE IF EXISTS comments CASCADE;
DROP TABLE IF EXISTS tasks CASCADE;
DROP TABLE IF EXISTS project_files CASCADE;
DROP TABLE IF EXISTS project_repositories CASCADE;
DROP TABLE IF EXISTS password_reset_tokens CASCADE;
DROP TABLE IF EXISTS projects CASCADE;
DROP TABLE IF EXISTS project_templates CASCADE;
DROP TABLE IF EXISTS refresh_tokens CASCADE;
DROP TABLE IF EXISTS users CASCADE;

CREATE TABLE users (
  id integer DEFAULT nextval('users_id_seq'::regclass) NOT NULL,
  username character varying(50) NOT NULL,
  email character varying(255) NOT NULL,
  password_hash text NOT NULL,
  created_at timestamp with time zone DEFAULT now(),
  password_changed_at timestamp with time zone DEFAULT now(),
  display_name character varying(80),
  status_message character varying(120),
  status_emoji character varying(12),
  avatar_mime character varying(120),
  avatar_data text,
  profile_updated_at timestamp with time zone,
  PRIMARY KEY (id),
  UNIQUE (email)
);

