CREATE TABLE projects (
  id integer DEFAULT nextval('projects_id_seq'::regclass) NOT NULL,
  user_id integer NOT NULL,
  title character varying(120) NOT NULL,
  description text NOT NULL,
  technologies text DEFAULT ''::text NOT NULL,
  visibility character varying(10) DEFAULT 'private'::character varying NOT NULL,
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now(),
  slug character varying(80) DEFAULT ''::character varying NOT NULL,
  CHECK (((visibility)::text = ANY ((ARRAY['private'::character varying, 'public'::character varying])::text[]))),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  PRIMARY KEY (id)
);

