CREATE TABLE project_repositories (
  id integer DEFAULT nextval('project_repositories_id_seq'::regclass) NOT NULL,
  project_id integer NOT NULL,
  label character varying(120) DEFAULT ''::character varying NOT NULL,
  url text NOT NULL,
  provider character varying(20) DEFAULT 'other'::character varying NOT NULL,
  sort_order integer DEFAULT 0 NOT NULL,
  created_at timestamp with time zone DEFAULT now(),
  CHECK (((provider)::text = ANY ((ARRAY['github'::character varying, 'gitlab'::character varying, 'bitbucket'::character varying, 'other'::character varying])::text[]))),
  FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
  PRIMARY KEY (id)
);

