CREATE TABLE project_files (
  id integer DEFAULT nextval('project_files_id_seq'::regclass) NOT NULL,
  project_id integer NOT NULL,
  parent_id integer,
  name character varying(255) NOT NULL,
  kind character varying(10) NOT NULL,
  content text DEFAULT ''::text NOT NULL,
  sort_order integer DEFAULT 0 NOT NULL,
  created_at timestamp with time zone DEFAULT now(),
  updated_at timestamp with time zone DEFAULT now(),
  encoding character varying(10) DEFAULT 'text'::character varying NOT NULL,
  mime_type character varying(120),
  CHECK (((encoding)::text = ANY ((ARRAY['text'::character varying, 'base64'::character varying])::text[]))),
  CHECK (((kind)::text = ANY ((ARRAY['file'::character varying, 'folder'::character varying])::text[]))),
  FOREIGN KEY (parent_id) REFERENCES project_files(id) ON DELETE CASCADE,
  FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
  PRIMARY KEY (id)
);

