      <path d="M78,812 Q76,790 92,786 Q92,806 78,812Z" fill="#555533" opacity="0.16"/>
      <path d="M94,812 Q94,790 108,792 Q107,808 94,812Z" fill="#555533" opacity="0.16"/>
      <path d="M108,818 Q112,798 124,802 Q120,818 108,818Z" fill="#555533" opacity="0.16"/>
