  <article class="info-card">
    <h2>Objectifs des animations</h2>
    <div class="phases">
      <div class="phase">
        <div class="phase-num"></div>
        <p class="phase-text">Sensibiliser les publics aux relations qui lient l''homme à la nature</p>
      </div>
      <div class="phase">
        <div class="phase-num"></div>
        <p class="phase-text">Mener une réflexion sur nos comportements vis-à-vis de l''environnement</p>
      </div>
      <div class="phase">
        <div class="phase-num"></div>
        <p class="phase-text">Amener à mieux respecter la nature et notre environnement au quotidien</p>
      </div>
      <div class="phase">
        <div class="phase-num"></div>
        <p class="phase-text">Sensibiliser à la transmission d''une terre vivable aux générations futures</p>
      </div>
    </div>
