  <script>
    if (window.matchMedia("(max-width: 800px)").matches) {
      document.querySelectorAll(".side-deco").forEach((node) => node.remove());
    }
  </script>

  <script>
    (() => {
      const navLinks = document.querySelector(".nav-links");
      const burger = document.getElementById("burger");
      if (!navLinks || !burger) return;

      function closeMenu() {
        navLinks.classList.remove("open");
        burger.classList.remove("open");
        burger.setAttribute("aria-expanded", "false");
        navLinks.querySelectorAll(".dropdown").forEach(dd => dd.classList.remove("open"));
      }

      document.querySelectorAll(".nav-links > li").forEach(li => {
        let timer;
        li.addEventListener("mouseenter", () => {
          clearTimeout(timer);
          const dd = li.querySelector(".dropdown");
          if (dd && window.innerWidth > 1120) dd.classList.add("open");
        });
        li.addEventListener("mouseleave", () => {
          timer = setTimeout(() => {
            const dd = li.querySelector(".dropdown");
            if (dd && window.innerWidth > 1120) dd.classList.remove("open");
          }, 150);
        });
      });

      burger.addEventListener("click", () => {
        const isOpen = navLinks.classList.toggle("open");
        burger.classList.toggle("open", isOpen);
        burger.setAttribute("aria-expanded", String(isOpen));
      });

      document.querySelectorAll(".nav-links > li > span").forEach(span => {
        span.addEventListener("click", event => {
          if (window.innerWidth > 1120) return;
          event.stopPropagation();
          const dropdown = span.nextElementSibling;
          if (!dropdown) return;
          dropdown.classList.toggle("open");
        });
      });

      document.addEventListener("click", event => {
        if (!burger.contains(event.target) && !navLinks.contains(event.target)) {
          closeMenu();
        }
      });

      navLinks.querySelectorAll("a").forEach(link => {
        link.addEventListener("click", () => {
          if (window.innerWidth <= 1120) closeMenu();
        });
      });

      document.addEventListener("keydown", event => {
        if (event.key === "Escape") closeMenu();
      });

      window.addEventListener("resize", () => {
        if (window.innerWidth > 1120) closeMenu();
      });
    })();
  </script>
</body>
</html>
